import math


def relu(x):
    return x if x > 0 else 0


def sigmoid(x):
    if x >= 0:
        return 1.0 / (1.0 + math.exp(-x))
    e = math.exp(x)
    return e / (1.0 + e)


def softmax(xs):
    m = max(xs)
    exps = [math.exp(x - m) for x in xs]
    total = sum(exps)
    return [e / total for e in exps]


if __name__ == "__main__":
    print(relu(3.0), relu(-5.0))
    print(sigmoid(0))
    print(softmax([1.0, 2.0, 3.0]))
